<?php
require_once __DIR__.'/../includes/auth_check.php';require_once __DIR__.'/../config/database.php';$uid=current_user_id();$type=$_GET['type']??'';$q=trim($_GET['q']??'');$sql="SELECT t.*,p.nama_barang,p.kode_barang,p.satuan FROM stock_transactions t JOIN products p ON p.id=t.product_id AND p.user_id=t.user_id WHERE t.user_id=?";$args=[$uid];if(in_array($type,['masuk','keluar'],true)){$sql.=" AND t.jenis=?";$args[]=$type;}if($q!==''){$sql.=" AND (p.nama_barang LIKE ? OR p.kode_barang LIKE ?)";$args[]="%$q%";$args[]="%$q%";}$sql.=" ORDER BY t.created_at DESC";$s=$pdo->prepare($sql);$s->execute($args);$rows=$s->fetchAll();$pageTitle='Riwayat Transaksi';$active='history';require __DIR__.'/../includes/header.php';
?>
<div class="page-actions"><div><span class="eyebrow">MUTASI PERSEDIAAN</span><h1>Riwayat transaksi</h1><p>Lihat catatan barang masuk dan barang keluar.</p></div><div class="split-actions"><a class="btn btn-success" href="../transactions/create.php?type=in">+ Barang masuk</a><a class="btn btn-primary" href="../transactions/create.php?type=out">− Barang keluar</a></div></div>
<section class="panel"><form class="toolbar" method="get"><div class="search-box"><i data-lucide="search"></i><input name="q" value="<?= e($q) ?>" placeholder="Cari nama atau kode barang..."></div><select name="type"><option value="">Semua transaksi</option><option value="masuk" <?= $type==='masuk'?'selected':'' ?>>Barang masuk</option><option value="keluar" <?= $type==='keluar'?'selected':'' ?>>Barang keluar</option></select><button class="btn btn-outline">Filter</button></form><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Barang</th><th>Jenis mutasi</th><th>Jumlah</th><th>Stok sebelum</th><th>Stok sesudah</th><th>Keterangan</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= date('d/m/Y H:i',strtotime($r['created_at'])) ?></td><td><b><?= e($r['nama_barang']) ?></b><small class="sub-cell"><?= e($r['kode_barang']) ?></small></td><td><span class="badge <?= $r['jenis']==='masuk'?'badge-green':'badge-blue' ?>"><?= ucfirst($r['jenis']) ?></span></td><td class="<?= $r['jenis']==='masuk'?'positive':'negative' ?>"><?= $r['jenis']==='masuk'?'+':'-' ?><?= (int)$r['jumlah'].' '.e($r['satuan']) ?></td><td><?= (int)$r['stok_sebelum'] ?></td><td><b><?= (int)$r['stok_sesudah'] ?></b></td><td><?= e($r['keterangan']?:'-') ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="7"><div class="empty-inline">Belum ada riwayat transaksi.</div></td></tr><?php endif; ?></tbody></table></div></section>
